package ru.zhukhly.bank;import android.graphics.*;import android.view.View;final class CardChip extends View{Paint p=new Paint(3);CardChip(android.content.Context c){super(c);}protected void onDraw(Canvas c){c.save();c.scale(getWidth()/76f,getHeight()/39f);p.setShader(new LinearGradient(0,0,40,39,new int[]{0xffa77b39,0xffffe6a3,0xffbd9149,0xffffdf91},null,Shader.TileMode.CLAMP));c.drawRoundRect(1,4,40,34,6,6,p);p.setShader(null);p.setColor(0xff80602e);p.setStrokeWidth(1);p.setStyle(Paint.Style.STROKE);c.drawRoundRect(13,10,28,28,3,3,p);for(int y=13;y<=26;y+=13){c.drawLine(1,y,13,y,p);c.drawLine(28,y,40,y,p);}c.drawLine(20,4,20,10,p);c.drawLine(20,28,20,34,p);p.setColor(0xffffd489);p.setStrokeWidth(2);p.setStrokeCap(Paint.Cap.ROUND);for(int i=0;i<3;i++)c.drawArc(43-i*4,13-i*5,57+i*5,25+i*5,-55,110,false,p);p.setStyle(Paint.Style.FILL);c.restore();}}